```java
import java.util.Arrays;

public class MergeSort {

    public static void sort(int[] array) {
        if (array.length < 2) {
            return; // Base case: array is already sorted if it has less than 2 elements
        }
        int mid = array.length / 2;
        int[] left = Arrays.copyOfRange(array, 0, mid); // Copy the first half of the array
        int[] right = Arrays.copyOfRange(array, mid, array.length); // Copy the second half of the array

        // Recursively sort both halves
        sort(left);
        sort(right);

        // Merge the sorted halves
        merge(array, left, right);
    }

    private static void merge(int[] result, int[] left, int[] right) {
        int i = 0, j = 0, k = 0;

        // Merge the two arrays while there are elements in both
        while (i < left.length && j < right.length) {
            if (left[i] <= right[j]) {
                result[k++] = left[i++];
            } else {
                result[k++] = right[j++];
            }
        }

        // Copy any remaining elements from the left array
        while (i < left.length) {
            result[k++] = left[i++];
        }

        // Copy any remaining elements from the right array
        while (j < right.length) {
            result[k++] = right[j++];
        }
    }

    public static void main(String[] args) {
        int[] sampleArray = { 34, 7, 23, 32, 5, 62 };
        MergeSort.sort(sampleArray);
        System.out.println(Arrays.toString(sampleArray)); // Should print the sorted array
    }
}
```

